    /**
     * PT21.4, review D-F4 (M8b): the whole of ingress for one webhook, with a certified adapter of the channel (the one
     * given, else the one connected): its verify, its nonce taken once in the store, the refusal or the receipts and
     * claims journaled on runtime:ingress, and each message delivered with the claims that adapter verified. An adapter
     * the certified package did not make, or of another kind, is refused as rt.connectChannel refuses it (PL6408).
     */
    receive(channel: string, w: Webhook, given?: ChannelAdapter): Promise<IngressAnswer>;
    /**
     * S191, S205 (PS15.4): the application instance a thread key names, `<channel>:<keyed digest of the key>`, with the
     * key kept in the erasable store. A host that creates a thread itself names it with this.
     */
    threadId(channel: string, key: string): Promise<string>;
    /** S191: the address a keyed digest names in the erasable store, or null when it is unknown or erased. */
    addressOf(d: string): string | null;
    /**
     * S205 (PS3.2): erases a body or an address: the body is deleted, its digest kept with an erasure record journaled on
     * runtime:content, and it is never stored again. The records the journal and the ledger keep by digest are refused.
     */
    erase(d: string): Promise<void>;
    /**
     * PT21.4, S182: what ingress records on runtime:ingress besides a delivery: a webhook its adapter refused (nothing
     * is dispatched), a provider's receipt for an earlier send, and the sender claims of a message (K11). The channel
     * must be one the certificate names.
     */
    ingressRecord(channel: string, record: {
        stage: 'verify' | 'receipt' | 'claims';
        outcome: string;
        provider: string;
        reason?: string;
        providerId?: string;
        status?: string;
        claims?: {
            verified: boolean;
            sender: string;
            principal?: string;
        };
        messageId?: string;
    }): Promise<void>;
    /**
     * PT21.4: takes a provider's nonce once (Mailgun's token). The store keeps it until `until`, the time after which the
     * adapter refuses its signature as stale, so a replay after a restart is refused too. Review D-F6 (M8b): each nonce
     * keeps its own expiry, computed from the provider's timestamp, so a provider clock ahead of ours cannot outlive it.
     */
    claimNonce(channel: string, key: string, until: number, now: number): Promise<boolean>;
    /** PS16.2: the current grant instance of a credential and holder, or null. */
    grantOf(c: string, holder: string | null): string | null;
    takeAuthorizations(): {
        credential: string;
        url: string;
    }[];
    /** PS16.4: a person's signed revocation, matched to its grant by its subject. */
    private revokeBySubject;
    /** S327: a channel's class in the program's audience: the one it declares, else the lowest. */
    private channelClass;
    /** S321: the id of the project's anchor, which a memory record names. */
    get anchorId(): string | null;
    /** PS17.5 (S309): a person's signed record of the kind verify promotes a memory item to verified, once. */
    verifyMemory(item: string, record: unknown): Promise<void>;
    /**
     * PS17.7 (S306): a person's signed record of the kind forget erases every body about a subject, or from a source, removes
     * the items that name it, asks each connected adapter to forget the subject, and records what it erased by digest.
     */
    forget(target: {
        subject: string;
    } | {
        source: string;
    }, record: unknown): Promise<{
        erased: string[];
    }>;
    /** PS11.3a: each erased body, with the hash of the forget event that erased it (null for an erasure on its own). */
    forgottenBodies(): Map<string, string | null>;
    /** PS16.4: what a person signs to revoke the current grant of a credential and holder. */
    revocationSubject(c: string, holder: string | null): string;
    /**
     * PT22.3, PT10g: asks the holder for a grant: the Grant instance is created (a new one after a revocation) or asked
     * again, and the vault's authorization URL is returned for the host to deliver. The URL is never journaled.
     */
    requestGrant(c: string, holder: string | null): Promise<string>;
    /**
     * PT10f, S202 (CredentialHost): the holder's consent, from the provider's redirect, as Callback(granted); true when
     * the grant took it (review C2, M9). A grant id is the credential's by its own prefix only (review C8, M9).
     */
    grantCallback(c: string, grantId: string, scopes: string[]): Promise<boolean>;
    /** PT10f (CredentialHost): a callback's outcome, on runtime:ingress; never a code, a state or a token. */
    credentialRecord(credential: string, record: {
        stage: 'callback';
        outcome: 'refused' | 'granted';
        provider: string;
        reason?: string;
    }): Promise<void>;
    /**
     * PS16.4: revokes the current grant of a credential and holder: from the provider, a security signal, or a person's
     * signed record of the kind revocation, by a key of the people ring. The source is recorded on runtime:ingress.
     */
    revokeGrant(c: string, holder: string | null, opts: {
        source: 'provider' | 'security' | 'person';
        record?: unknown;
    }): Promise<void>;
    /**
     * PS16.3, S199: the grant check of an intent whose effect uses a credential, read as of now: no vault, no grant, or a
     * grant not Granted is credential-unavailable; a scope it does not hold is insufficient-scope.
     */
    grantCheck(instanceId: string, decl: {
        uses?: {
            credential: string;
            scopes: string[];
            holder: string | null;
        };
    } | null, payload: Record<string, unknown>): {
        deny: string;
        reads?: Record<string, number>;
    } | {
        credential: {
            name: string;
            grantState: string;
            scopes: string[];
        };
        reads: Record<string, number>;
    } | null;
    /** PT22.5: the vault's transport for an intent of an effect that uses a credential, bound to the intent's grant. */
    apiFor(decl: {
        uses?: {
            credential: string;
            holder: string | null;
        };
    } | null, payload: Record<string, unknown>): ApiTransport | undefined;
    /**
     * PS17.0, PT10j (S460): the handle a source's adapter is built with, for credential c, which a source of the build names
     * and which has no holder. Each request is refused before it is sent when its URL lies outside the provider's base
     * addresses (PL6406, audited as a capability refusal is) and while c's one grant is not Granted (credential-unavailable,
     * read at the request, so a revocation stops the next one); otherwise it goes through the vault's withToken for the
     * grant, which attaches the token and strips it from the answer. The handle holds no token and no way to get one: its
     * one method is request, and the runtime keeps which handles it made.
     *
     * S461 (PS17.0, PT10j): for credential c with holder Principal, which an owned source names, each owner of the source's
     * items has a grant of its own, grant:<c>:<keyed digest of the owner>#<n> (PT10g). With no owner, the handle is the
     * routing handle the source's adapter is built with: inside a retrieval from a source that names c (RETRIEVAL, set by
     * the runtime around the adapter's retrieve, envelope and resolve) it sends under the grant of that retrieval's owner,
     * and outside one it refuses (credential-unavailable). With an owner, it is that owner's handle, for the host's sync of
     * that owner: it sends under that owner's grant only, refuses a request made inside a retrieval for another owner
     * (owner-mismatch, permanent, nothing sent), and refuses while that grant is not Granted. Both check the base addresses
     * first, as above. An owner's handle for a credential with no holder is refused: it has one grant and no owner.
     * Messages name no owner: a holder is named by its keyed digest only (S191).
     */
    credentialHandle(c: string, owner?: string): Readonly<{
        request(r: {
            method: string;
            url: string;
            headers?: Record<string, string>;
            body?: string;
        }): Promise<HttpResponse>;
    }>;
    /**
     * PT10f, S200: the vault of a credential the certificate names, made by the certified adapter package, of the store the
     * certificate binds (PL6408 otherwise). The runtime holds it for the grant check and `api` (PT22.4, PT22.5).
     */
    connectVault(credential: string, adapter: VaultAdapter): void;
    /** PT26, S308: binds a source's adapter; only one the certified poly-io made, of the kind the source declares. */
    connectSource(source: string, adapter: SourceAdapter): void;
    connectChannel(channel: string, adapter: ChannelAdapter, transports: ChannelTransports): void;
    takeApprovals(dir: string): Promise<{
        file: string;
        outcome: 'applied' | 'refused';
        reason?: ApprovalRefusal;
    }[]>;
    /** The outbox rows of an instance (polyrun's), for hosts and tests that watch the intents. */
    outbox(instanceId: string): Promise<import("@cognitive-fab/polygraph/polyrun/src/index.mjs").OutboxRow[]>;
    /** One outbox row by its intent id (its status and attempts), or null. */
    outboxRow(intentId: string): Promise<{
        intent_id: string;
        instance_id: string;
        kind: string;
usage: poly check <file.poly | project dir> [--json] [--root <dir>] [--host <tsconfig>]
       poly edit-check <module> --old <text> --new <text> | --text <file text> [--project <dir>] [--apply] [--json]
       poly fmt <file.poly> [--write] [--json]
       poly mcp      (an MCP server over stdio: the registry's commands as tools)
       poly lsp      (the language server over stdio, on both surfaces)
       poly new "<description>" --into <file.poly>   (drafts with the headless provider under your login; never admitted)
       poly install --host <adapter> [--project <dir>]   (prints a host's entries from adapters/<adapter>/install.json)
       poly run --mcp [--project <dir>]   (the workflow tools over stdio, on poly-runtime, from poly.json's run field)
       poly witness <id> --trace | --test [--root <dir>] [--out <file>]
       poly fix <id> [--root <dir>]
       poly lint handlers [project dir]
       poly admit <project dir>
       poly admit --witness <file | project dir> --key <private key file> [--root <dir>] [--out <file>]
       poly approve <intent> --by <keyId> --key <private key file> --db <store> [--out <file>]
       poly accept <witness id> --by <keyId> --key <private key file> [--root <dir>]
       poly anchor keyrings --out <file outside the project> [--production] [--project <dir>]
       poly anchor production on|off [--project <dir>]
       poly sign keyrings --by <keyId> --key <private key file> [--project <dir>]
       poly sign policy <scope> --by <keyId> --key <private key file> [--project <dir>]
       poly memory-verify --item <id> --by <keyId> --key <private key file> [--out <file>] [--project <dir>]
       poly forget --subject <principal> | --source <source> --by <keyId> --key <private key file> [--out <file>] [--project <dir>]
       poly grant-request --credential <c> [--for <holder>] --by <keyId> --key <private key file> --out <file>   (a request for the runtime's approvals folder)
       poly grant-revoke --grant <instance id> | --credential <c> --db <store> --by <keyId> --key <private key file> [--out <file>]
       poly journal verify --db <store> --trust <keyId>=<public key file> [--run <id>]
       poly journal replay --db <store> --build <dir> --certificate <file> --trust <keyId>=<file> [--run <id>]
       poly journal export --db <store> --run <id>
       poly bench gate [--sizes 1,8,64] [--out <file>]
       poly journal eval --db <store> --decision <d> --candidate <provider module>
       poly journal fit --db <store> --decision <d> --model <id> [--version <n>] [--out <file>]
       poly try <file> --machine <M> --ops <file.json> [--out <trace.json>]   (a playground: nothing is admitted, run or written)
       poly cost --db <store> [--run <id>] [--scope <module>] [--period YYYY-MM-DD | YYYY-MM] [--prices <file>]

  check    Parses, types and lowers each module; runs strict validate(), translation
           validation (poly-ref), polygraph's model check and poly-ref's deadlock, liveness,
           effect, composition and configuration checks; prints the verdict with its checked
           instance, and writes the report to <root>/.poly/report.json.
  witness  Writes the witness with that id as {pre, action, data, post} windows (--trace),
           or as a host test that walks it and asserts the violated predicate (--test).
  fix      Applies the fix with that id if its target node still has the digest it was
           computed on; otherwise refuses it with PL0201 STALE_FIX.

  --json        print the report as JSON (diagnostics in poly.diagnostic/1 form)
  --root <dir>  where .poly/ lives (default: the project directory, or the working directory)
  --out <file>  where `poly witness` writes (default: .poly/witness/<id prefix>.<ext>)

  admit    Checks the project and, when it is CLEAN, writes .poly/certificate.json, signed
           with the admission key poly.json names by location (keys.admission, S126).

  export   traces: a certified build's journals as a trace corpus file (PF10.1, PT29): values for declared
           domains, salted tokens for the rest, erased steps left out and counted. Never over MCP.

