// The stateful core of the refund agent: one Order instance per order in orders.json, keyed by the order id.
// A customer asks for a refund (of the whole order or of one line), confirms the quote, and the refund is issued
// through Stripe. Every amount sent to Stripe is computed here from the prices loaded at Open.
module support

type Pick = All | Line { i: 0..3 }

type Phase =
  | New
  | Ready
  | Quoted  { what: Pick }      // a quote the customer has to confirm
  | Issuing { what: Pick }      // the refund was sent to Stripe
  | Review  { what: Pick }      // Stripe could not be reached: a person decides whether it went through
  | Closed                      // everything was refunded

enum Notice { Issued, Declined, UnderReview }
enum Why { Declined, Unreachable }

machine Order {
  state {
    phase     : Phase                 = New
    lines     : 0..4                  = 0
    price     : map<0..3, 0..1000000> = [0, 0, 0, 0]
    done      : map<0..3, bool>       = [false, false, false, false]
    total     : 0..4000000            = 0
    remaining : 0..4000000            = 0
    refunded  : 0..4000000            = 0
  }
  terminal phase is Closed

  action Open(lines: 1..4, total: 1..4000000, p0: 0..1000000, p1: 0..1000000, p2: 0..1000000, p3: 0..1000000)
  action RequestAll()
  action RequestLine(line: 0..3)
  action Confirm()
  action Cancel()
  action Expire()
  action Refunded()
  action RefundFailed(why: Why)
  action ResolveIssued()
  action ResolveNotIssued()

  on Open {
    require phase is New else reject "already-open"
    require p0 > 0 else reject "bad-line"
    require (lines >= 2 && p1 > 0) || (lines < 2 && p1 == 0) else reject "bad-line"
    require (lines >= 3 && p2 > 0) || (lines < 3 && p2 == 0) else reject "bad-line"
    require (lines >= 4 && p3 > 0) || (lines < 4 && p3 == 0) else reject "bad-line"
    require p0 + p1 + p2 + p3 == total else reject "total-mismatch"
    phase' = Ready
    lines' = lines
    price' = [p0, p1, p2, p3]
    total' = total
    remaining' = total
  }

  on RequestAll {
    require phase is Ready || phase is Quoted else reject "busy"
    require remaining > 0 else reject "nothing-to-refund"
    phase' = Quoted { what: All }
    after 30m -> Expire() as expiry
  }

  on RequestLine(line) {
    require phase is Ready || phase is Quoted else reject "busy"
    require line < lines else reject "no-such-line"
    require !done[line] else reject "already-refunded"
    phase' = Quoted { what: Line { i: line } }
    after 30m -> Expire() as expiry
  }

  on Confirm {
    match phase {
      Quoted { what: w } => {
        match w {
          All => {
            require remaining > 0 else reject "nothing-to-refund"
            cancel expiry
            phase' = Issuing { what: All }
            emit refund(amount: remaining)
          }
          Line { i: n } => {
            cancel expiry
            phase' = Issuing { what: Line { i: n } }
            emit refund(amount: price[n])
          }
        }
      }
      _ => reject "no-quote"
    }
  }

  on Cancel {
    require phase is Quoted else reject "no-quote"
    cancel expiry
    phase' = Ready
  }

  on Expire {
    require phase is Quoted else reject "no-quote"
    phase' = Ready
  }

  on Refunded {
    match phase {
      Issuing { what: w } => {
        match w {
          All => {
            phase' = Closed
            done' = [true, true, true, true]
            refunded' = refunded + remaining
            remaining' = 0
            emit notify(event: Issued, amount: remaining)
          }
          Line { i: n } => {
            if remaining == price[n] { phase' = Closed } else { phase' = Ready }
            done' = done with [n] = true
            refunded' = refunded + price[n]
            remaining' = remaining - price[n]
            emit notify(event: Issued, amount: price[n])
          }
        }
      }
      _ => reject "not-issuing"
    }
  }

  on RefundFailed(why) {
    match phase {
      Issuing { what: w } => {
        if why == Why.Unreachable {
          phase' = Review { what: w }
          emit notify(event: UnderReview, amount: 0)
        } else {
          phase' = Ready
          emit notify(event: Declined, amount: 0)
        }
      }
      _ => reject "not-issuing"
    }
  }

  // A person looked in the Stripe dashboard: the refund went through.
  on ResolveIssued {
    match phase {
      Review { what: w } => {
        match w {
          All => {
            phase' = Closed
            done' = [true, true, true, true]
            refunded' = refunded + remaining
            remaining' = 0
            emit notify(event: Issued, amount: remaining)
          }
          Line { i: n } => {
            if remaining == price[n] { phase' = Closed } else { phase' = Ready }
            done' = done with [n] = true
            refunded' = refunded + price[n]
            remaining' = remaining - price[n]
            emit notify(event: Issued, amount: price[n])
          }
        }
      }
      _ => reject "not-in-review"
    }
  }

  // A person looked in the Stripe dashboard: no refund was made; the customer may ask again.
  on ResolveNotIssued {
    require phase is Review else reject "not-in-review"
    phase' = Ready
    emit notify(event: Declined, amount: 0)
  }

  effect refund(amount: 1..4000000) {
    kind "stripe.refund"
    labels { egress:external, read:private, read:store }
    targets { egress: exact "https://api.stripe.com/v1/refunds", secrets: ["STRIPE_SECRET_KEY"], store: ["orders"] }
    class irreversible
    retry { attempts 3, base 1s, timeout 20s }
    idempotent header "Idempotency-Key" window 24h
    ok -> Refunded()
    failed -> RefundFailed(why: Declined)
    exhausted -> RefundFailed(why: Unreachable)
  }

  effect notify(event: Notice, amount: 0..4000000) {
    kind "whatsapp.notify"
    labels { egress:external, read:private, read:store }
    targets { egress: "https://graph.facebook.com/v21.0", secrets: ["WHATSAPP_TOKEN"], store: ["orders", "whatsapp"] }
    class irreversible
    retry { attempts 1 }
  }

  invariant refunds-add-up: refunded + remaining == total
  invariant closed-means-all-refunded: phase is Closed implies remaining == 0
  invariant nothing-refunded-before-open: phase is New implies refunded == 0
  step property refund-never-exceeds-total: post.refunded <= post.total
  step property refunded-never-shrinks: post.refunded >= pre.refunded
  liveness issuing-settles: (phase is Issuing) leads to !(phase is Issuing)
    under fair { Refunded | RefundFailed(*) }
}

