602	    verifyChain(instanceId: string): Promise<ChainResult>;
603	    /** PT16: an `advice` event (a Polyx verdict) on a run; it has no write path into the program. */
604	    advise(instanceId: string, verdict: unknown): Promise<LedgerEvent>;
