606	    signHeads(only?: string): Promise<SignedHead[]>;
607	    heads(instanceId: string): Promise<SignedHead[]>;
608	    /** S123: an anchor over the latest signed head of every run, for the period it names. */
609	    /** PD5.4b, S108: countersigns the latest signed head of each run through the host's adapter. */
610	    countersignHeads(adapter: CountersignAdapter): Promise<Countersignature[]>;
