620	    /**
621	     * Archives a terminal instance: its `closure` event, then polyrun's purge, in one transaction, then its head is
622	     * signed (S122, S123). The chain outlives the purge; polyrun 8.4.0 drops the dedupe keys with the journal, which
623	     * K4 forbids, until E1 (S124).
624	     */
625	    archive(instanceId: string): Promise<LedgerEvent>;
626	    /** A run's chain, signed heads and the bodies its step events name, for an auditor (PT16 trace export). */
627	    exportRun(instanceId: string): Promise<{
628	        events: LedgerEvent[];
629	        heads: SignedHead[];
630	        bodies: Record<string, unknown>;
631	    }>;
