    const r = await dispatch(order, 'Confirm', {}, actionId)
    if (r.stepKind !== 'accepted') {
      if (r.rejectReason === 'no-quote') return (await busyText(order, r.state)) ?? `There is no refund waiting for your confirmation on ${order.order}. Offers are valid for 30 minutes; send "refund ${order.order}" to start again.`
